// Entry for bundlers with WebAssembly ESM integration (webpack 5 `asyncWebAssembly`,
// Vite with vite-plugin-wasm, Rspack): the wasm-bindgen `bundler` target imports its .wasm
// as a module and initializes itself.
import { bind } from "./common.js";
import type { WasmApi } from "./types.js";

export * from "./common.js";

export const { openStore, loadWasm } = bind(async (simd) => {
  // @ts-ignore the glue is generated by wasm-bindgen into dist/wasm before this file is used
  const glue: WasmApi = await (simd ? import("./wasm/bundler/simd/hms_wasm.js") : import("./wasm/bundler/scalar/hms_wasm.js"));
  return glue;
});
